-- Executar após 10_escritorio_ecommtabil.sql
SELECT set_config('app.escritorio_id', (SELECT id::text FROM escritorios WHERE slug = 'ecommtabil'), false);

-- Dia = coluna ROTINA (DIA) da Planilha Central; sem rotina definida = dia 15

SELECT r.id, e.ordem, e.nome FROM rotinas r
CROSS JOIN (VALUES (1, 'Importar Notas'), (2, 'Jogar para o movimento'), (3, 'Ajuste Receita Simples')) AS e(ordem, nome)
WHERE r.escritorio_id = esc() AND r.titulo = 'FECHAMENTO FISCAL';
